def text(language, key, **values):
    return TEXT[key][1 if language == "fr" else 0].format(**values)


def issue_text(language, code):
    return ISSUES[code][1 if language == "fr" else 0]


def error_text(language, code):
    key = "contract" if code.startswith("contract.") else code
    return ERRORS.get(key, ERRORS["input_or_output.unavailable"])[1 if language == "fr" else 0]


def number_text(language, value):
    return value.replace(".", ",") if language == "fr" else value
